def transformation(S):
    S_new = []
    if len(S) == 0:
        return S_new
    S_new.append(S[0])
    for i in range(len(S) - 1):
        s = S[i] + S[i+1]
        S_new.append(s)
        S_new.append(S[i+1])
    return S_new

def count_value(S, V):
    return S.count(V)

# Initial sequence for N=3, a_i = i
S = [1, 2, 3]
V = 5

print(f"k=0: S={S}, Count({V})={count_value(S, V)}")

for k in range(1, 5):
    S = transformation(S)
    count = count_value(S, V)
    print(f"k={k}: S_length={len(S)}, Count({V})={count}")

